typedef struct {
    char name[21];
    int w;
    int s;
} Food;

int main() {
    int n;
    while (1) {
        scanf("%d", &n);
        if (n == 0) break;

        Food foods[10];
        for (int i = 0; i < n; i++) {
            scanf("%s %d %d", foods[i].name, &foods[i].w, &foods[i].s);
        }

        int indices[10];
        for (int i = 0; i < n; i++) indices[i] = i;

        int best_order[10];
        double best_g = DBL_MAX;

        do {
            // Check strength constraints
            int valid = 1;
            int weight_above = 0;
            for (int i = n - 1; i >= 0; i--) {
                if (weight_above > foods[indices[i]].s) {
                    valid = 0;
                    break;
                }
                weight_above += foods[indices[i]].w;
            }
            if (!valid) continue;

            // Compute center of gravity
            int total_weight = 0;
            double weighted_sum = 0.0;
            for (int i = 0; i < n; i++) {
                total_weight += foods[indices[i]].w;
                weighted_sum += (i + 1) * foods[indices[i]].w;
            }
            double g = weighted_sum / total_weight;

            if (g < best_g) {
                best_g = g;
                for (int i = 0; i < n; i++) best_order[i] = indices[i];
            }
        } while (next_permutation(indices, n));

        for (int i = 0; i < n; i++) {
            if (i > 0) printf(" ");
            printf("%s", foods[best_order[i]].name);
        }
        printf("\n");
    }
    return 0;
}

// Simple next_permutation for int array
int next_permutation(int *arr, int n) {
    int i = n - 2;
    while (i >= 0 && arr[i] >= arr[i + 1]) i--;
    if (i < 0) return 0;
    int j = n - 1;
    while (arr[j] <= arr[i]) j--;
    int temp = arr[i]; arr[i] = arr[j]; arr[j] = temp;
    for (int left = i + 1, right = n - 1; left < right; left++, right--) {
        temp = arr[left]; arr[left] = arr[right]; arr[right] = temp;
    }
    return 1;
}

