void solve(int *arr, int used[], int depth) {
    if (depth == n) {
        // Check validity and compute G
        int total_w = 0;
        for (int i = 0; i < n; i++) total_w += w[arr[i]];

        int above = 0;
        // Check from top to bottom: item at position depth-1 (top) has 0 above it
        // item at position i (0-indexed from bottom) has sum of w[i+1..n-1] above
        // Compute suffix sums
        int suffix = 0;
        for (int i = n-1; i >= 0; i--) {
            // item arr[i] must bear 'suffix' weight
            if (s[arr[i]] < suffix) return;
            suffix += w[arr[i]];
        }

        // Compute G numerator (position is 1-indexed)
        double num = 0;
        for (int i = 0; i < n; i++) {
            num += (i+1) * w[arr[i]];
        }
        double G = num / total_w;

        if (!found || G < best_G) {
            best_G = G;
            found = 1;
            for (int i = 0; i < n; i++) best_perm[i] = arr[i];
        }
        return;
    }

    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            used[i] = 1;
            arr[depth] = i;
            solve(arr, used, depth+1);
            used[i] = 0;
        }
    }
}

