#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAXN 10
#define MAXNAME 25
#define INF 1000000000

typedef struct {
    char name[MAXNAME];
    int w, s;
} Item;

Item a[MAXN];
int n;

int sumW[1 << MAXN];
int feasible[1 << MAXN];
long long dp[1 << MAXN];
int parentMask[1 << MAXN];
int parentItem[1 << MAXN];

int main(void) {
    while (1) {
        if (scanf("%d", &n) != 1) return 0;
        if (n == 0) break;

        for (int i = 0; i < n; i++) {
            scanf("%20s %d %d", a[i].name, &a[i].w, &a[i].s);
        }

        int totalMasks = 1 << n;
        sumW[0] = 0;
        for (int mask = 1; mask < totalMasks; mask++) {
            int b = mask & -mask;
            int idx = 0;
            while ((1 << idx) != b) idx++;
            sumW[mask] = sumW[mask ^ b] + a[idx].w;
        }

        feasible[0] = 1;
        for (int mask = 1; mask < totalMasks; mask++) feasible[mask] = 0;

        dp[0] = 0;
        for (int mask = 1; mask < totalMasks; mask++) {
            dp[mask] = LLONG_MAX / 4;
            parentMask[mask] = -1;
            parentItem[mask] = -1;
        }

        for (int mask = 0; mask < totalMasks; mask++) {
            if (!feasible[mask]) continue;

            int k = 0;
            for (int t = mask; t; t &= (t - 1)) k++;

            for (int i = 0; i < n; i++) {
                if (mask & (1 << i)) continue;

                if (a[i].s >= sumW[mask]) {
                    int newMask = mask | (1 << i);
                    feasible[newMask] = 1;

                    long long newCost = dp[mask] + (long long)(k + 1) * a[i].w;

                    if (newCost < dp[newMask]) {
                        dp[newMask] = newCost;
                        parentMask[newMask] = mask;
                        parentItem[newMask] = i;
                    } else if (newCost == dp[newMask]) {
                        /* Tie-break lexicographically by resulting sequence of names */
                        int seq1[MAXN], seq2[MAXN], len1 = 0, len2 = 0;

                        int cur = newMask;
                        while (cur) {
                            seq1[len1++] = parentItem[cur];
                            cur = parentMask[cur];
                        }
                        for (int l = 0, r = len1 - 1; l < r; l++, r--) {
                            int tmp = seq1[l]; seq1[l] = seq1[r]; seq1[r] = tmp;
                        }

                        cur = mask;
                        while (cur) {
                            seq2[len2++] = parentItem[cur];
                            cur = parentMask[cur];
                        }
                        for (int l = 0, r = len2 - 1; l < r; l++, r--) {
                            int tmp = seq2[l]; seq2[l] = seq2[r]; seq2[r] = tmp;
                        }
                        seq2[len2++] = i;

                        int better = 0;
                        for (int p = 0; p < len1 && p < len2; p++) {
                            int cmp = strcmp(a[seq2[p]].name, a[seq1[p]].name);
                            if (cmp < 0) { better = 1; break; }
                            if (cmp > 0) { better = 0; break; }
                        }

                        if (better) {
                            parentMask[newMask] = mask;
                            parentItem[newMask] = i;
                        }
                    }
                }
            }
        }

        int full = totalMasks - 1;
        int order[MAXN], len = 0;
        int cur = full;
        while (cur) {
            order[len++] = parentItem[cur];
            cur = parentMask[cur];
        }

        for (int i = len - 1; i >= 0; i--) {
            puts(a[order[i]].name);
        }
    }

    return 0;
}

