using namespace std;

struct Food {
    string name;
    int w, s;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    while (cin >> n && n != 0) {
        vector<Food> foods(n);
        for (int i = 0; i < n; ++i) {
            cin >> foods[i].name >> foods[i].w >> foods[i].s;
        }
        // dp[mask] = {max_load_capacity_on_top, best_center_gravity_numerator, best_weight_sum}
        // We store the best arrangement for each mask
        // For equal max_load, choose lower center of gravity (lower numerator/weight)
        struct State {
            int load; // maximum additional weight that can be placed on top of this stack (i.e., min of (s_i - sum of weights above i) )
            long long num; // numerator of center of gravity (sum of position * weight)
            int weight; // total weight
            int prev; // previous mask (for reconstruction)
            int added; // index of last added item
        };
        vector<State> dp(1 << n, {-1, 0, 0, -1, -1});
        dp[0] = {INT_MAX, 0, 0, -1, -1};
        for (int mask = 0; mask < (1 << n); ++mask) {
            if (dp[mask].load == -1) continue;
            int cur_load = dp[mask].load;
            long long cur_num = dp[mask].num;
            int cur_weight = dp[mask].weight;
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) continue;
                int new_mask = mask | (1 << i);
                // Check if item i can bear the current stack on top of it
                if (foods[i].s < cur_weight) continue;
                // New load capacity on top of new stack = min(cur_load, foods[i].s - cur_weight)
                int new_load = min(cur_load, foods[i].s - cur_weight);
                // New numerator: positions increase by 1 for existing items, new item at position 1 (bottom)
                // Actually we are building from bottom to top, so when we add a new item below,
                // all existing items' positions increase by 1.
                // New numerator = cur_num + cur_weight (since each existing item's position increases by 1)
                // + 1 * foods[i].weight (new bottom item at position 1)
                long long new_num = cur_num + cur_weight + foods[i].w;
                int new_weight = cur_weight + foods[i].w;
                // For tie-breaking: higher load is better, then lower center of gravity (num/weight)
                if (dp[new_mask].load == -1 ||
                    new_load > dp[new_mask].load ||
                    (new_load == dp[new_mask].load && 
                     new_num * dp[new_mask].weight < dp[new_mask].num * new_weight)) {
                    dp[new_mask] = {new_load, new_num, new_weight, mask, i};
                }
            }
        }
        int full = (1 << n) - 1;
        vector<int> order;
        int cur = full;
        while (cur != 0) {
            order.push_back(dp[cur].added);
            cur = dp[cur].prev;
        }
        // order is from top to bottom, we need bottom to top output
        for (int i = (int)order.size() - 1; i >= 0; --i) {
            cout << foods[order[i]].name << "\n";
        }
    }
    return 0;
}

