using namespace std;

struct Item {
    string name;
    int w, s;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    while (true) {
        int n;
        if (!(cin >> n)) return 0;
        if (n == 0) break;

        vector<Item> a(n);
        for (int i = 0; i < n; ++i) {
            cin >> a[i].name >> a[i].w >> a[i].s;
        }

        int N = 1 << n;

        // sumW[mask] = total weight of items in mask
        vector<int> sumW(N, 0);
        for (int mask = 1; mask < N; ++mask) {
            int b = __builtin_ctz(mask);
            int pmask = mask ^ (1 << b);
            sumW[mask] = sumW[pmask] + a[b].w;
        }

        const long long INF = (1LL << 60);

        // dp[mask] = minimum numerator of center-of-gravity expression
        // for stacking exactly items in mask (from bottom to top), among valid stacks.
        vector<long long> dp(N, INF);
        vector<int> parentMask(N, -1), parentItem(N, -1);

        dp[0] = 0;

        for (int mask = 0; mask < N; ++mask) {
            if (dp[mask] == INF) continue;

            int k = __builtin_popcount((unsigned)mask); // current number of items in stack
            int aboveWeight = sumW[mask];

            // Add a new item as the new bottom item.
            for (int i = 0; i < n; ++i) {
                if (mask & (1 << i)) continue;
                if (a[i].s < aboveWeight) continue; // would be crushed

                int nmask = mask | (1 << i);

                // Existing items move up by 1 level, new bottom contributes 1*w_i.
                // New numerator = old + totalWeightAbove + w_i
                long long cand = dp[mask] + aboveWeight + a[i].w;

                if (cand < dp[nmask]) {
                    dp[nmask] = cand;
                    parentMask[nmask] = mask;
                    parentItem[nmask] = i;
                } else if (cand == dp[nmask]) {
                    // Tie-break lexicographically by resulting sequence bottom->top
                    // Reconstruct both only when needed (n <= 10, so this is fine).
                    vector<int> seq1, seq2;

                    // candidate sequence
                    {
                        int curMask = mask;
                        vector<int> rev;
                        while (curMask) {
                            rev.push_back(parentItem[curMask]);
                            curMask = parentMask[curMask];
                        }
                        reverse(rev.begin(), rev.end());
                        seq1.push_back(i);
                        for (int x : rev) seq1.push_back(x);
                    }

                    // existing best sequence for nmask
                    {
                        int curMask = nmask;
                        vector<int> rev;
                        while (curMask) {
                            rev.push_back(parentItem[curMask]);
                            curMask = parentMask[curMask];
                        }
                        reverse(rev.begin(), rev.end());
                        seq2 = rev;
                    }

                    bool better = false;
                    for (int t = 0; t < (int)seq1.size(); ++t) {
                        if (a[seq1[t]].name < a[seq2[t]].name) {
                            better = true;
                            break;
                        } else if (a[seq1[t]].name > a[seq2[t]].name) {
                            break;
                        }
                    }
                    if (better) {
                        parentMask[nmask] = mask;
                        parentItem[nmask] = i;
                    }
                }
            }
        }

        int full = N - 1;

        // Reconstruct bottom -> top
        vector<int> ans;
        int cur = full;
        while (cur) {
            ans.push_back(parentItem[cur]);
            cur = parentMask[cur];
        }

        for (int idx : ans) {
            cout << a[idx].name << "\n";
        }
    }

    return 0;
}

