public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (true) {
            int n = sc.nextInt();
            if (n == 0) break;

            String[] names = new String[n];
            int[] w = new int[n];
            int[] s = new int[n];

            for (int i = 0; i < n; i++) {
                names[i] = sc.next();
                w[i] = sc.nextInt();
                s[i] = sc.nextInt();
            }

            // dp[mask] = best arrangement for items in mask
            // store as (minGravityNumerator, totalWeight, order)
            // We'll store as double for comparison but keep exact numerator/denominator
            int totalMasks = 1 << n;
            double[] bestG = new double[totalMasks];
            int[] bestWeight = new int[totalMasks];
            int[] bestPrev = new int[totalMasks];
            int[] bestLast = new int[totalMasks];
            Arrays.fill(bestG, Double.MAX_VALUE);
            bestG[0] = 0;
            bestWeight[0] = 0;

            for (int mask = 0; mask < totalMasks; mask++) {
                if (bestG[mask] == Double.MAX_VALUE) continue;
                int totalWeightBelow = bestWeight[mask];
                int totalItemsBelow = Integer.bitCount(mask);

                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) continue;
                    // Check if item i can bear the weight above it
                    // s[i] must be >= totalWeightBelow (weight of items above)
                    if (s[i] >= totalWeightBelow) {
                        int newMask = mask | (1 << i);
                        int newTotalWeight = totalWeightBelow + w[i];
                        // gravity contribution: (totalItemsBelow+1) * w[i] + previous numerator
                        // Actually we need to compute: sum(position * weight)
                        // position = totalItemsBelow+1 (since we add on top)
                        double newG = (bestG[mask] * bestWeight[mask] + (totalItemsBelow + 1) * w[i]) / (double) newTotalWeight;

                        if (newG < bestG[newMask] - 1e-9) {
                            bestG[newMask] = newG;
                            bestWeight[newMask] = newTotalWeight;
                            bestPrev[newMask] = mask;
                            bestLast[newMask] = i;
                        }
                    }
                }
            }

            // Reconstruct order from bottom to top
            int mask = totalMasks - 1;
            List<Integer> order = new ArrayList<>();
            while (mask != 0) {
                int item = bestLast[mask];
                order.add(item);
                mask = bestPrev[mask];
            }
            Collections.reverse(order);

            // Output bottom to top
            for (int idx : order) {
                System.out.println(names[idx]);
            }
        }
        sc.close();
    }
}

