            double bestG = Double.MAX_VALUE;
            int[] bestPerm = null;

            // Generate all permutations
            int[] indices = perm.clone();
            do {
                // Check validity
                boolean valid = true;
                int totalWeight = 0;
                for (int i = 0; i < n; i++) totalWeight += w[indices[i]];

                int weightAbove = 0;
                // Check from top to bottom
                // weightAbove for item at position i (0-indexed from bottom) = sum of w[i+1..n-1]
                // Compute suffix sums
                int[] suffixSum = new int[n + 1];
                for (int i = n - 1; i >= 0; i--) {
                    suffixSum[i] = suffixSum[i + 1] + w[indices[i]];
                }

                for (int i = 0; i < n; i++) {
                    int above = suffixSum[i + 1]; // sum of weights above position i
                    if (s[indices[i]] < above) {
                        valid = false;
                        break;
                    }
                }

                if (valid) {
                    // Compute G
                    double G = 0;
                    for (int i = 0; i < n; i++) {
                        G += (i + 1) * w[indices[i]];
                    }
                    G /= totalWeight;

                    if (G < bestG) {
                        bestG = G;
                        bestPerm = indices.clone();
                    }
                }

            } while (nextPermutation(indices));

            for (int i = 0; i < n; i++) {
                System.out.println(names[bestPerm[i]]);
            }
        }
    }

    static boolean nextPermutation(int[] arr) {
        int n = arr.length;
        int i = n - 2;
        while (i >= 0 && arr[i] >= arr[i + 1]) i--;
        if (i < 0) {
            // Reset to first permutation
            Arrays.sort(arr);
            return false;
        }
        int j = n - 1;
        while (arr[j] <= arr[i]) j--;
        int tmp = arr[i]; arr[i] = arr[j]; arr[j] = tmp;
        // Reverse from i+1 to end
        int left = i + 1, right = n - 1;
        while (left < right) {
            tmp = arr[left]; arr[left] = arr[right]; arr[right] = tmp;
            left++; right--;
        }
        return true;
    }
}

