public class Main {
    static class Item {
        String name;
        int w, s;
        Item(String name, int w, int s) {
            this.name = name;
            this.w = w;
            this.s = s;
        }
    }

    static class State {
        boolean possible;
        long cost; // sum of position * weight for this subset stack
        int totalWeight;
        int last; // top item index used to reconstruct
        int prevMask;

        State() {
            possible = false;
            cost = Long.MAX_VALUE / 4;
            totalWeight = 0;
            last = -1;
            prevMask = -1;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        while (true) {
            Integer nObj = fs.nextIntNullable();
            if (nObj == null) break;
            int n = nObj;
            if (n == 0) break;

            Item[] items = new Item[n];
            for (int i = 0; i < n; i++) {
                String name = fs.next();
                int w = fs.nextInt();
                int s = fs.nextInt();
                items[i] = new Item(name, w, s);
            }

            int size = 1 << n;
            int[] sumW = new int[size];
            for (int mask = 1; mask < size; mask++) {
                int b = mask & -mask;
                int idx = Integer.numberOfTrailingZeros(b);
                sumW[mask] = sumW[mask ^ b] + items[idx].w;
            }

            State[] dp = new State[size];
            for (int i = 0; i < size; i++) dp[i] = new State();
            dp[0].possible = true;
            dp[0].cost = 0;
            dp[0].totalWeight = 0;

            for (int mask = 1; mask < size; mask++) {
                int total = sumW[mask];
                dp[mask].totalWeight = total;

                for (int top = 0; top < n; top++) {
                    if ((mask & (1 << top)) == 0) continue;

                    int prev = mask ^ (1 << top);
                    if (!dp[prev].possible) continue;

                    int aboveWeight = items[top].w;
                    // In prev stack, every item's load increases by weight(top),
                    // so bottom item of prev must be able to bear new extra load.
                    // Easier formulation:
                    // If top is placed above prev stack, then top bears 0 and prev remains valid.
                    // But since order is bottom->top, removing top from mask leaves bottom portion prev.
                    // Validity requires every item in prev already supports only items above it in prev,
                    // unchanged by adding top on top. So only prev validity matters.
                    // No extra condition for top.
                    // This means building by adding top works naturally.

                    long candidateCost = dp[prev].cost + (long) Integer.bitCount(mask) * items[top].w;

                    // However, prev bottom items now also support top's weight, so above statement is wrong.
                    // Need explicit feasibility of placing top above prev:
                    // every item in prev gets extra load items[top].w.
                    // Instead, use reverse construction: choose bottom item.
                }
            }

            // Recompute with correct DP: choose bottom item.
            for (int i = 0; i < size; i++) dp[i] = new State();
            dp[0].possible = true;
            dp[0].cost = 0;
            dp[0].totalWeight = 0;

            for (int mask = 1; mask < size; mask++) {
                dp[mask].totalWeight = sumW[mask];
                int total = sumW[mask];
                int posBottom = 1;
                for (int bottom = 0; bottom < n; bottom++) {
                    if ((mask & (1 << bottom)) == 0) continue;
                    int rest = mask ^ (1 << bottom);
                    if (!dp[rest].possible) continue;

                    int weightAbove = sumW[rest];
                    if (items[bottom].s < weightAbove) continue;

                    long candidateCost = dp[rest].cost + total; 
                    // If bottom is added under rest, every item in rest shifts up by 1:
                    // new cost = 1*w_bottom + sum_{rest}(oldPos+1)*w = oldCost + sumW(rest) + w_bottom = oldCost + total

                    if (!dp[mask].possible || candidateCost < dp[mask].cost) {
                        dp[mask].possible = true;
                        dp[mask].cost = candidateCost;
                        dp[mask].last = bottom;   // store bottom
                        dp[mask].prevMask = rest;
                    }
                }
            }

            int full = size - 1;
            List<String> order = new ArrayList<>();
            int cur = full;
            while (cur != 0) {
                int bottom = dp[cur].last;
                order.add(items[bottom].name);
                cur = dp[cur].prevMask;
            }

            for (String name : order) {
                out.append(name).append('\n');
            }
        }

        System.out.print(out.toString());
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            int c;
            do {
                c = read();
            } while (c != -1 && c <= ' ');
            if (c == -1) return null;

            StringBuilder sb = new StringBuilder();
            while (c != -1 && c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        Integer nextIntNullable() throws IOException {
            String s = next();
            if (s == null) return null;
            return Integer.parseInt(s);
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
